export const todayAnchor=Date.parse('2026-11-02T01:00:00Z');
export function todayRows(){const row=(id,kind='action',status='open')=>({id,data:{title:`合成正式事项 ${id}`,kind,owner:kind==='action'?'我':'合成负责人',priority:'medium',tags:['合成'],due:null,followup:null},status,version:1,source:'signed_ai',createdAtMs:todayAnchor-1000,updatedAtMs:todayAnchor-1000,completedAtMs:status==='completed'?todayAnchor:null,deletedAtMs:status==='deleted'?todayAnchor:null});const point=atMs=>({atMs,timeZone:'Asia/Shanghai',localText:'2026-11-02T10:00'});const a=row('today-action');a.data.due=point(todayAnchor+3600000);a.version=3;const b=row('today-followup','followup');b.data.due=point(todayAnchor+86400000);b.data.followup=point(todayAnchor);b.version=4;return [a,b,row('today-undated'),row('today-completed','action','completed'),row('today-deleted','action','deleted')];}
export function todayAnswer(facts,alternate=false){const single=code=>({code,relatedTodoId:null,relatedTodoVersion:null});const ranking=facts.todos.filter(todo=>todo.status==='open').map(todo=>({todoId:todo.id,todoVersion:todo.version,reasons:[single(todo.kind==='action'?'open_action':'open_followup'),...(todo.overdue?[single('overdue')]:todo.dueDate===null&&todo.followupDate===null?[single('undated')]:todo.dueDate===facts.date?[single('due_today')]:todo.followupDate===facts.date?[single('followup_today')]:[])]}));if(alternate)ranking.reverse();return {snapshotId:facts.snapshotId,date:facts.date,timeZone:facts.timeZone,ranking};}
